      "path": "packages/helmd/src/tools/caseflow.ts",
      "content": "// Case lifecycle tools: begin_case / case_status / record_finding / save_evidence /\n// end_case — every one of them reads or writes the session's active case. External tool\n// discovery (find_tool) lives in ./tool-discovery.ts; it touches no case state.\n\nimport type { Context } from '@deepseek-ai/cordis'\nimport { defineTool } from '@deepseek-ai/dsh-tools'\nimport { existsSync } from 'node:fs'\nimport { resolve, join } from 'node:path'\nimport {\n  bindCase, getCase, unbindCase, createCaseDir, loadCaseMd, closeCase,\n  validateEvidenceIds, appendFinding, saveEvidence, countEvidence,\n  casesRoot, findOpenCaseOnDisk, loadCaseInfoFromDisk, auditCasesRoot,\n  listLooseFilesInCase,\n} from '../case.js'\nimport { getLevel } from '../mode.js'\nimport { renderAdvisoryStats } from '../advisory.js'\nimport { getStreamInterceptionStats } from '../llm-stream-hook.js'\n\ninterface ExecLike {\n  agent?: {\n    id?: string\n    cwd?: string\n    workspace?: string\n    session?: {\n      header?: {\n        cwd?: string\n      }\n    }\n  }\n}\n\nfunction resolveWorkspaceRoot(root?: string, exec?: ExecLike): string | undefined {\n  return root?.trim() || exec?.agent?.session?.header?.cwd || exec?.agent?.cwd || exec?.agent?.workspace\n}\n\nconst RULES = [\n  '1. Built-in tools first; missing capability → find_tool() (GitHub); custom scripts LAST, only in <case>/scripts/.',\n  '2. External CLI output → save_evidence(label, ...) before citing it.',\n  '3. Parameters come from prior tool output in evidence/. Findings cite E ids via record_finding.',\n  '4. Resume after compaction → case_status(); before compaction, bring the CASE.md `## resume` block up to date.',\n  '5. Installed a tool or learned a verified usage → tool_memory(register/note) with evidence id; a tactic failing 3 times in a row on the same target (no new evidence) → tool_memory note target=deadend, and never retry a filed dead end without new evidence.',\n].join('\\n')\n\nexport function registerCaseflowTools(ctx: Context): void {\n  ctx.tools.register(defineTool({\n    name: 'begin_case',\n    description:\n      'Start a case workspace for one sample/investigation: creates <workspace>/helmd-cases/<date>-<slug>/ ' +\n      '(sample/, evidence/, scripts/, CASE.md), hashes samples as first evidence, routes the goal, and binds it to this session. ' +\n      'Call before analyzing a new sample. Pass root = the workspace directory shown in your environment when unsure.',\n    parameters: {\n      goal: { type: 'string', required: true, description: 'What this investigation must deliver.' },\n      samples: { type: 'array', items: { type: 'string' }, description: 'Absolute paths of sample files to ingest.' },\n      root: { type: 'string', description: 'Workspace root; defaults to session cwd, HELMD_CASES_DIR, or process cwd.' },\n      force: { type: 'boolean', description: 'Force open a new case even if an uncompleted open case exists on disk.' },\n    },\n    output: { schema: { type: 'string' }, render: (_a: unknown, v: string) => [{ type: 'text', text: v }] },\n    async execute(args: { goal: string; samples?: string[]; root?: string; force?: boolean }, exec?: ExecLike) {\n      const effectiveRoot = resolveWorkspaceRoot(args.root, exec)\n      const existing = getCase(exec?.agent?.id)\n      if (existing) {\n        return `A case is already active for this session: ${existing.name}\\nClose it with end_case() before opening another.`\n      }\n      if (!args.force) {\n        const openCase = await findOpenCaseOnDisk(effectiveRoot)\n        if (openCase) {\n          return [\n            `Notice: an unclosed case is already open on disk: ${openCase.name}`,\n            `Goal: ${openCase.goal}`,\n            '',\n            `Options:`,\n            `1. Resume it: call case_status(name: \"${openCase.name}\")`,\n            `2. Close it first: call end_case(summary: \"...\")`,\n            `3. Force new case: call begin_case(goal: \"...\", force: true)`,\n          ].join('\\n')\n        }\n      }\n      const mode = getLevel(exec?.agent?.id)\n      const info = await createCaseDir({\n        goal: args.goal ?? 'unspecified',\n        samples: args.samples ?? [],\n        mode,\n        route: 'pending (route_task)',\n        root: effectiveRoot,\n      })\n      bindCase(exec?.agent?.id, info)\n      return [\n        `case opened: ${info.dir}`,\n        `mode: ${mode}`,\n        '',\n        RULES,\n      ].join('\\n')\n    },\n  }))\n\n  ctx.tools.register(defineTool({\n    name: 'case_status',\n    description:\n      'Re-read the active case state from disk (CASE.md header, samples, recent timeline). ' +\n      'Call this FIRST when resuming a task after context compaction — disk state survives what the conversation loses. ' +\n      'Can also resume an existing case by name or inspect cases on disk.',\n    parameters: {\n      name: { type: 'string', description: 'Optional case folder name to resume (or \"open\"/\"latest\" to rebind the most recent open case).' },\n      root: { type: 'string', description: 'Optional workspace root directory.' },\n    },\n    output: { schema: { type: 'string' }, render: (_a: unknown, v: string) => [{ type: 'text', text: v }] },\n    async execute(args: { name?: string; root?: string }, exec?: ExecLike) {\n      const effectiveRoot = resolveWorkspaceRoot(args.root, exec)\n      let active = getCase(exec?.agent?.id)\n\n      if (args.name) {\n        if (args.name === 'open' || args.name === 'latest') {\n          const found = await findOpenCaseOnDisk(effectiveRoot)\n          if (found) {\n            bindCase(exec?.agent?.id, found)\n            active = found\n          } else {\n            return `No unclosed open case found on disk under ${casesRoot(effectiveRoot)}.`\n          }\n        } else {\n          const fromDisk = await loadCaseInfoFromDisk(args.name, effectiveRoot)\n          if (fromDisk) {\n            bindCase(exec?.agent?.id, fromDisk)\n            active = fromDisk\n          } else {\n            return `Case '${args.name}' not found under ${casesRoot(effectiveRoot)}.`\n          }\n        }\n      }\n\n      if (!active) {\n        const base = casesRoot(effectiveRoot)\n        const audit = await auditCasesRoot(effectiveRoot)\n        const parts: string[] = [\n          `No case bound to this session. Recent case dirs (if any) live under ${base} — inspect and re-run begin_case if resuming.`,\n        ]\n        if (audit.cases.length > 0) {\n          parts.push('\\nCases on disk:')\n          for (const c of audit.cases.slice(0, 5)) {\n            parts.push(`  - ${c.name} [${c.status}] (${c.evidenceCount} evidence): ${c.goal.slice(0, 60)}`)\n          }\n        }\n        if (audit.strays.length > 0) {\n          parts.push(`\\n[Notice] Non-case items found under helmd-cases: ${audit.strays.join(', ')}`)\n        }\n        const openCase = audit.cases.find((c) => c.status === 'open')\n        if (openCase) {\n          parts.push(`\\nActive unclosed case: ${openCase.name}. To resume: case_status(name: \"${openCase.name}\")`)\n        }\n        return parts.join('\\n')\n      }\n\n      const md = await loadCaseMd(active.dir)\n      const lines = md.split('\\n')\n      const head = lines.slice(0, lines.indexOf('## timeline') >= 0 ? lines.indexOf('## timeline') : 12).join('\\n')\n      const timeline = lines.filter((l) => l.startsWith('- [')).slice(-5).join('\\n')\n      // The resume block is the handoff contract: it must survive a truncated window.\n      const resumeAt = lines.findIndex((l) => l.startsWith('## resume'))\n      const resume = resumeAt >= 0 ? lines.slice(resumeAt).join('\\n').trim() : ''\n\n      const loose = await listLooseFilesInCase(active.dir)\n      const looseNotice = loose.length > 0\n        ? `\\n\\n[Warning] ${loose.length} loose unorganized file(s) in case root (will auto-archive to evidence/ on end_case): ${loose.join(', ')}`\n        : ''\n\n      return [\n        `case: ${active.name}`,\n        `dir: ${active.dir}`,\n        '',\n        head,\n        '',\n        'recent timeline:',\n        timeline || '  (empty)',\n        looseNotice,\n        ...(resume ? ['', resume] : []),\n        '',\n        RULES,\n        ...(renderAdvisoryStats() ? ['', renderAdvisoryStats()] : []),\n        ...(getStreamInterceptionStats().count > 0\n          ? ['', `[流式拒答拦截监控]\\n已拦截拒答: ${getStreamInterceptionStats().count} 次 | 最近拦截: ${getStreamInterceptionStats().lastTime || '无'}\\n审计日志文件: ${getStreamInterceptionStats().logFile}`]\n          : ['', `[流式拒答拦截监控]\\n状态: 监控中 (当前会话拦截 0 次) | 审计日志文件: ${getStreamInterceptionStats().logFile}`]),\n      ].join('\\n')\n    },\n  }))\n\n  ctx.tools.register(defineTool({\n    name: 'record_finding',\n    description:\n      'Record a conclusion into findings.md. Every evidence id you cite is validated against the evidence/ directory — ' +\n      'citing ids that do not exist is rejected. This is how conclusions stay guess-free.',\n    parameters: {\n      title: { type: 'string', required: true },\n      detail: { type: 'string', required: true },\n      evidence_ids: { type: 'array', items: { type: 'string' }, required: true, description: 'e.g. [\"E-002\",\"E-005\"]' },\n    },\n    output: { schema: { type: 'string' }, render: (_a: unknown, v: string) => [{ type: 'text', text: v }] },\n    async execute(args: { title: string; detail: string; evidence_ids: string[] }, exec?: ExecLike) {\n      const active = getCase(exec?.agent?.id)\n      if (!active) return 'No active case. begin_case() first — findings need an evidence chain.'\n      const check = await validateEvidenceIds(active.dir, args.evidence_ids ?? [])\n      if (!check.ok) {\n        return [\n          `REJECTED — unknown evidence ids: ${check.missing.join(', ')}`,\n          `known ids: ${check.known.join(', ') || '(none)'}`,\n          'Cite only ids that exist in evidence/. Run the tool that produces the proof first.',\n        ].join('\\n')\n      }\n      await appendFinding(active.dir, args.title, args.detail, args.evidence_ids ?? [])\n      return `finding recorded: ${args.title} [${(args.evidence_ids ?? []).join(', ')}]`\n    },\n  }))\n\n  ctx.tools.register(defineTool({\n    name: 'end_case',\n    description:\n      'Close the active case: stamps CASE.md completed and unbinds the session. ' +\n      'In deep mode at least one recorded finding is required before closing. ' +\n      'Closing also requires at least one evidence entry on disk, unless the summary states why there is none ' +\n      'with \"(no-evidence: …)\".',\n    parameters: { summary: { type: 'string', description: 'One-line closing summary.' } },\n    output: { schema: { type: 'string' }, render: (_a: unknown, v: string) => [{ type: 'text', text: v }] },\n    async execute(args: { summary?: string }, exec?: ExecLike) {\n      const active = getCase(exec?.agent?.id)\n      if (!active) return 'No active case bound to this session.'\n      const mode = getLevel(exec?.agent?.id)\n      if (mode === 'deep') {\n        const fm = await import('node:fs/promises').then((m) => m.readFile(join(active.dir, 'findings.md'), 'utf8'))\n        const count = (fm.match(/^## /gm) ?? []).length\n        if (count === 0) {\n          return 'DEEP mode requires at least one record_finding before end_case. Evidence chain incomplete.'\n        }\n      }\n      // Completion is an external fact, not a self-report: a closed case must point at\n      // evidence on disk, or say in words why it has none.\n      const evidence = await countEvidence(active.dir)\n      if (evidence === 0 && !/\\(no-evidence:\\s*\\S/i.test(args.summary ?? '')) {\n        return [\n          'REJECTED — 关闭前必须交代证据：evidence/ 里一条 E-xxx 都没有。',\n          '两条路径：① 先落地证据（跑工具，或 save_evidence(label, ...)）再关闭；',\n          '② 本次确实无证据（纯咨询 / 被阻塞）就在 summary 里写明：',\n          '   summary: \"… (no-evidence: 用户仅咨询，未接触样本)\"。',\n        ].join('\\n')\n      }\n      await closeCase(active.dir, args.summary)\n      unbindCase(exec?.agent?.id)\n      const stats = renderAdvisoryStats()\n      return [`case closed: ${active.name}${args.summary ? ` — ${args.summary}` : ''}`, ...(stats ? ['', stats] : [])].join('\\n')\n    },\n  }))\n\n  ctx.tools.register(defineTool({\n    name: 'save_evidence',\n    description:\n      'Persist arbitrary output into the active case evidence chain with an E-number. ' +\n      'Use for external CLI tools run via shell whose output would otherwise leave no trace. ' +\n      'Findings may cite these ids exactly like tool-generated ones.',\n    parameters: {\n      label: { type: 'string', required: true, description: 'Short source label, e.g. \"themida-dump\".' },\n      content: { type: 'string', description: 'Text to store.' },\n      file: { type: 'string', description: 'Path of a file to store instead of inline content.' },\n    },\n    output: { schema: { type: 'string' }, render: (_a: unknown, v: string) => [{ type: 'text', text: v }] },\n    async execute(args: { label: string; content?: string; file?: string }, exec?: ExecLike) {\n      const active = getCase(exec?.agent?.id)\n      if (!active) return 'No active case. begin_case() first — evidence needs a home.'\n      let content = args.content ?? ''\n      if (!content && args.file) {\n        if (!existsSync(resolve(args.file))) return `file not found: ${args.file}`\n        content = `<copied from file: ${resolve(args.file)}>\\n` +\n          await import('node:fs/promises').then((m) => m.readFile(resolve(args.file!), 'utf8'))\n      }\n      if (!content.trim()) return 'nothing to save (empty content)'\n      const { id } = await saveEvidence(active.dir, args.label, content, args.label)\n      return `[evidence: ${id} saved to ${active.name}]`\n    },\n  }))\n}\n"
    },
    {
      "path": "packages/helmd/src/persist.ts",
      "content": "// persistToCase: wraps ctx.tools.register once in apply() so every domain\n// tool gains evidence persistence with zero per-tool edits. Soft gate:\n// without an active case tools behave exactly as before (plus a footer).\n\nimport type { Context } from '@deepseek-ai/cordis'\nimport { getCase, saveEvidence } from './case.js'\n\nconst NO_PERSIST = new Set([\n  // knowledge / router / session tools — outputs are not case artifacts\n  'skill_catalog', 'read_reference', 'analysis_mode', 'route_task',\n  'evidence_reference', 'native_reference', 'web_reference',\n  'malware_reference', 'ai_reference', 'protocol_reference',\n  'tool_recommend', 'find_tool',\n  // case lifecycle itself\n  'begin_case', 'case_status', 'record_finding', 'end_case', 'save_evidence',\n])\n\nexport function isNoPersist(toolName: string): boolean {\n  return NO_PERSIST.has(toolName)\n}\n\nasync function persistHook(sessionId: string | undefined, toolName: string, result: unknown): Promise<unknown> {\n  if (typeof result !== 'string') return result\n  const active = getCase(sessionId)\n  if (!active) {\n    return result + '\\n[no active case — output NOT persisted. begin_case(goal, samples) keeps evidence.]'\n  }\n  const firstLine = result.split('\\n').find((l) => l.trim()) ?? ''\n  const { id } = await saveEvidence(active.dir, toolName, result, firstLine)\n  return result + `\\n[evidence: ${id} saved to ${active.name}]`\n}\n\n/**\n * Wrap register so every later-registered tool executes through the hook.\n * Must be called BEFORE any register*Tools(ctx) in apply().\n */\nexport function applyPersistenceWrap(ctx: Context): () => void {\n  const target = ctx.tools as unknown as {\n    register: (def: { name: string; execute?: (...a: any[]) => any }) => void\n  }\n  const originalRegister = target.register\n  target.register = (def) => {\n    if (!def || typeof def.execute !== 'function' || isNoPersist(def.name)) {\n      return originalRegister.call(ctx.tools, def)\n    }\n    const original = def.execute.bind(def)\n    ;(def as any).execute = async (args: unknown, exec?: { agent?: { id?: string } }) => {\n      const result = await original(args, exec)\n      return await persistHook(exec?.agent?.id, def.name, result)\n    }\n    return originalRegister.call(ctx.tools, def)\n  }\n  return () => {\n    target.register = originalRegister\n  }\n}\n"
    },
    {
      "path": "packages/helmd/src/case.ts",
      "content": "// Case workspace core — pure fs/state operations, no cordis deps.\n// Everything a case needs lives on disk; the in-memory map only binds\n// a session (exec.agent.id) to its active case dir for convenience.\n\nimport { createHash } from 'node:crypto'\nimport { createReadStream, existsSync } from 'node:fs'\nimport { mkdir, copyFile, writeFile, appendFile, readFile, readdir, rename } from 'node:fs/promises'\nimport { join, resolve, basename } from 'node:path'\n\nexport interface CaseInfo {\n  dir: string\n  name: string\n  goal: string\n  mode: string\n  route: string\n}\n\nconst bindings = new Map<string, CaseInfo>()\n\nexport function getCase(sessionId?: string): CaseInfo | undefined {\n  return bindings.get(sessionId ?? '__global__')\n}\n\nexport function bindCase(sessionId: string | undefined, info: CaseInfo): void {\n  bindings.set(sessionId ?? '__global__', info)\n}\n\nexport function unbindCase(sessionId?: string): CaseInfo | undefined {\n  const key = sessionId ?? '__global__'\n  const info = bindings.get(key)\n  bindings.delete(key)\n  return info\n}\n\n/** Root resolution: explicit arg > HELMD_CASES_DIR > process.cwd(). */\nexport function casesRoot(root?: string): string {\n  const base = root?.trim() || process.env.HELMD_CASES_DIR?.trim() || process.cwd()\n  return resolve(base, 'helmd-cases')\n}\n\nexport function slugify(text: string, max = 48): string {\n  const clean = text\n    .replace(/[\\\\/:\\*\\?\"<>\\|]+/g, ' ')\n    .trim()\n    .replace(/[^\\p{L}\\p{N}_-]+/gu, '-')\n    .replace(/^-+|-+$/g, '')\n    .slice(0, max)\n    .replace(/-+$/g, '')\n  return clean || 'case'\n}\n\nfunction today(): string {\n  const d = new Date()\n  const p = (n: number) => String(n).padStart(2, '0')\n  return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())}`\n}\n\nfunction nowStamp(): string {\n  const d = new Date()\n  const p = (n: number) => String(n).padStart(2, '0')\n  return `${p(d.getHours())}:${p(d.getMinutes())}:${p(d.getSeconds())}`\n}\n\nasync function sha256File(path: string): Promise<string> {\n  return await new Promise((resolvePromise, reject) => {\n    const hash = createHash('sha256')\n    const stream = createReadStream(path)\n    stream.on('data', (chunk) => hash.update(chunk))\n    stream.on('end', () => resolvePromise(hash.digest('hex')))\n    stream.on('error', reject)\n  })\n}\n\n/** Create <root>/helmd-cases/<date>-<slug>[/] with collision suffixes. */\nexport async function createCaseDir(opts: {\n  goal: string\n  samples: string[]\n  mode: string\n  route: string\n  root?: string\n}): Promise<CaseInfo> {\n  const base = casesRoot(opts.root)\n  const hint = slugify(opts.goal || basename(opts.samples[0] ?? ''))\n  let name = `${today()}-${hint}`\n  for (let i = 2; existsSync(join(base, name)); i++) name = `${today()}-${hint}-${i}`\n\n  const dir = join(base, name)\n  for (const sub of ['sample', 'evidence', 'scripts']) {\n    await mkdir(join(dir, sub), { recursive: true })\n  }\n\n  const lines: string[] = []\n  let id = 0\n  for (const sample of opts.samples) {\n    if (!existsSync(sample)) throw new Error(`sample not found: ${sample}`)\n    const dest = join(dir, 'sample', basename(sample))\n    await copyFile(sample, dest)\n    const sha = await sha256File(dest)\n    id++\n    const eid = `E-${String(id).padStart(3, '0')}`\n    await writeFile(join(dir, 'evidence', `${eid}-sha256.txt`),\n      `${sha}  ${basename(sample)}\\nsource: ${resolve(sample)}\\n`, 'utf8')\n    lines.push(`  - sample/${basename(sample)} sha256:${sha}`)\n  }\n\n  const caseMd = [\n    `# CASE ${name}`,\n    `status: open`,\n    `mode: ${opts.mode}`,\n    `route: ${opts.route}`,\n    `goal: ${opts.goal}`,\n    ...(lines.length ? ['samples:', ...lines] : []),\n    '',\n    '## timeline',\n    `- [${nowStamp()}] BEGIN — created by begin_case`,\n    '',\n    '## resume（压缩恢复契约：恢复时先 case_status()；压缩前把 1-6 更新到当前）',\n    '1. 目标与用户约束：goal + 用户说过的范围/边界（安全相关约束逐字保留，不要转述）',\n    '2. 已确认事实：验证过的结论 + 对应 E-id（未验证的猜测不要写进来）',\n    '3. 关键参数：命令 / 偏移 / 哈希 / 工具版本 —— 正文只写 E-id，细节留在 evidence/',\n    '4. 已排除的路线：试过且失败的路子（同步进 DEAD_ENDS，写明根因）',\n    '5. 当前进展：正在做的这一步、做到哪、下一步的最小动作',\n    '6. 待办与阻塞：等材料 / 等外部结果 / 等用户技术选择（写明等什么、由谁给）',\n    '',\n  ].join('\\n')\n  await writeFile(join(dir, 'CASE.md'), caseMd, 'utf8')\n  await writeFile(join(dir, 'findings.md'), `# FINDINGS ${name}\\n`, 'utf8')\n\n  return { dir, name, goal: opts.goal, mode: opts.mode, route: opts.route }\n}\n\n/** Evidence files present for a case (E-xxx entries), counted from disk. */\nexport async function countEvidence(caseDir: string): Promise<number> {\n  const files = await readdir(join(caseDir, 'evidence')).catch(() => [] as string[])\n  return files.filter((f) => /^E-\\d{3}/.test(f)).length\n}\n\n/**\n * Next evidence id for one case directory.\n *\n * The directory is scanned once per case, not once per save: this runs on the\n * tool-call path for EVERY domain tool while a case is open, and a readdir grows\n * with the evidence count. After the first scan the counter is process-local —\n * the case directory is created and owned by this process, so no external writer\n * can invalidate it. Restart safety is preserved by the initial scan.\n */\nconst evidenceCounters = new Map<string, number>()\n\n/** Next E-number = max existing + 1; the scan happens once per case directory. */\nexport async function nextEvidenceId(caseDir: string): Promise<string> {\n  const cached = evidenceCounters.get(caseDir)\n  if (cached !== undefined) {\n    const next = cached + 1\n    evidenceCounters.set(caseDir, next)\n    return `E-${String(next).padStart(3, '0')}`\n  }\n  const files = await readdir(join(caseDir, 'evidence')).catch(() => [] as string[])\n  let max = 0\n  for (const f of files) {\n    const m = /^E-(\\d{3})-/.exec(f)\n    if (m) max = Math.max(max, parseInt(m[1], 10))\n  }\n  evidenceCounters.set(caseDir, max + 1)\n  return `E-${String(max + 1).padStart(3, '0')}`\n}\n\n/** Drop a case directory's counter (called when its case closes). */\nexport function resetEvidenceCounter(caseDir: string): void {\n  evidenceCounters.delete(caseDir)\n}\n\nexport async function saveEvidence(\n  caseDir: string,\n  toolLabel: string,\n  content: string,\n  summary: string,\n): Promise<{ id: string; path: string }> {\n  const id = await nextEvidenceId(caseDir)\n  const safeTool = toolLabel.replace(/[^a-zA-Z0-9_-]+/g, '_').slice(0, 40) || 'output'\n  const capped = content.length > 256 * 1024\n    ? content.slice(0, 256 * 1024) + `\\n[truncated at 256KB; full length ${content.length}]\\n`\n    : content\n  const path = join(caseDir, 'evidence', `${id}-${safeTool}.txt`)\n  await writeFile(path, capped, 'utf8')\n  await appendTimeline(caseDir, `${toolLabel} → ${id} — ${summary.slice(0, 80)}`)\n  return { id, path }\n}\n\nexport async function appendTimeline(caseDir: string, line: string): Promise<void> {\n  await appendFile(join(caseDir, 'CASE.md'), `- [${nowStamp()}] ${line}\\n`, 'utf8')\n}\n\nexport async function loadCaseMd(caseDir: string): Promise<string> {\n  return await readFile(join(caseDir, 'CASE.md'), 'utf8')\n}\n\nexport async function validateEvidenceIds(\n  caseDir: string,\n  ids: string[],\n): Promise<{ ok: boolean; missing: string[]; known: string[] }> {\n  const files = await readdir(join(caseDir, 'evidence')).catch(() => [] as string[])\n  const known = files\n    .map((f) => /^(E-\\d{3})-/.exec(f)?.[1])\n    .filter((x): x is string => Boolean(x))\n  const missing = ids.filter((id) => !known.includes(id))\n  return { ok: missing.length === 0, missing, known }\n}\n\nexport async function appendFinding(\n  caseDir: string,\n  title: string,\n  detail: string,\n  ids: string[],\n): Promise<void> {\n  await appendFile(\n    join(caseDir, 'findings.md'),\n    `\\n## ${title}\\n${detail}\\nevidence: ${ids.join(', ')}\\n`,\n    'utf8',\n  )\n  await appendTimeline(caseDir, `FINDING — ${title} (${ids.join(', ')})`)\n}\n\nexport async function closeCase(caseDir: string, summary?: string): Promise<void> {\n  // 1. Auto-sweep any loose files left in case root to evidence/\n  const swept = await sweepCaseRootFiles(caseDir)\n  if (swept.length > 0) {\n    await appendTimeline(caseDir, `SWEEP — auto-archived loose files to evidence/: ${swept.join(', ')}`)\n  }\n\n  // 2. Mark completed\n  const md = await loadCaseMd(caseDir)\n  await writeFile(join(caseDir, 'CASE.md'), md.replace(/^status: open/m, 'status: completed'), 'utf8')\n  if (summary) await appendTimeline(caseDir, `END — ${summary.slice(0, 120)}`)\n  else await appendTimeline(caseDir, 'END — closed by end_case')\n}\n\nexport interface CaseSummary {\n  name: string\n  dir: string\n  status: 'open' | 'completed' | 'unknown'\n  goal: string\n  mode: string\n  route: string\n  evidenceCount: number\n  looseFiles: string[]\n}\n\n/** List all case directories under casesRoot with metadata. */\nexport async function listCasesOnDisk(root?: string): Promise<CaseSummary[]> {\n  const base = casesRoot(root)\n  if (!existsSync(base)) return []\n  try {\n    const entries = await readdir(base, { withFileTypes: true })\n    const results: CaseSummary[] = []\n    for (const entry of entries) {\n      if (!entry.isDirectory()) continue\n      const dirPath = join(base, entry.name)\n      const caseMdPath = join(dirPath, 'CASE.md')\n      if (existsSync(caseMdPath)) {\n        try {\n          const md = await readFile(caseMdPath, 'utf8')\n          const statusMatch = /^status:\\s*(open|completed)\\b/m.exec(md)\n          const goalMatch = /^goal:\\s*(.*)$/m.exec(md)\n          const modeMatch = /^mode:\\s*(.*)$/m.exec(md)\n          const routeMatch = /^route:\\s*(.*)$/m.exec(md)\n          const evidenceCount = await countEvidence(dirPath)\n          const looseFiles = await listLooseFilesInCase(dirPath)\n          results.push({\n            name: entry.name,\n            dir: dirPath,\n            status: (statusMatch?.[1] as any) ?? 'unknown',\n            goal: goalMatch?.[1]?.trim() ?? 'unspecified',\n            mode: modeMatch?.[1]?.trim() ?? 'full',\n            route: routeMatch?.[1]?.trim() ?? 'pending (route_task)',\n            evidenceCount,\n            looseFiles,\n          })\n        } catch {}\n      }\n    }\n    results.sort((a, b) => b.name.localeCompare(a.name))\n    return results\n  } catch {\n    return []\n  }\n}\n\n/** Check for non-case stray directories or files sitting directly in helmd-cases/. */\nexport async function auditCasesRoot(root?: string): Promise<{ cases: CaseSummary[]; strays: string[] }> {\n  const base = casesRoot(root)\n  const cases = await listCasesOnDisk(root)\n  const strays: string[] = []\n  if (!existsSync(base)) return { cases, strays }\n  try {\n    const entries = await readdir(base, { withFileTypes: true })\n    for (const entry of entries) {\n      if (entry.isFile()) {\n        strays.push(`file:${entry.name}`)\n      } else if (entry.isDirectory()) {\n        const caseMdPath = join(base, entry.name, 'CASE.md')\n        if (!existsSync(caseMdPath)) {\n          strays.push(`dir:${entry.name}`)\n        }\n      }\n    }\n  } catch {}\n  return { cases, strays }\n}\n\n/** Find the most recently created case marked status: open. */\nexport async function findOpenCaseOnDisk(root?: string): Promise<CaseInfo | undefined> {\n  const all = await listCasesOnDisk(root)\n  const open = all.find((c) => c.status === 'open')\n  if (!open) return undefined\n  return {\n    dir: open.dir,\n    name: open.name,\n    goal: open.goal,\n    mode: open.mode,\n    route: open.route,\n  }\n}\n\n/** Load a specific case by directory or folder name. */\nexport async function loadCaseInfoFromDisk(caseDirOrName: string, root?: string): Promise<CaseInfo | undefined> {\n  const base = casesRoot(root)\n  const dirPath = caseDirOrName.includes('/') || caseDirOrName.includes('\\\\')\n    ? resolve(caseDirOrName)\n    : join(base, caseDirOrName)\n  const caseMdPath = join(dirPath, 'CASE.md')\n  if (!existsSync(caseMdPath)) return undefined\n  try {\n    const md = await readFile(caseMdPath, 'utf8')\n    const goalMatch = /^goal:\\s*(.*)$/m.exec(md)\n    const modeMatch = /^mode:\\s*(.*)$/m.exec(md)\n    const routeMatch = /^route:\\s*(.*)$/m.exec(md)\n    return {\n      dir: dirPath,\n      name: basename(dirPath),\n      goal: goalMatch?.[1]?.trim() ?? 'unspecified',\n      mode: modeMatch?.[1]?.trim() ?? 'full',\n      route: routeMatch?.[1]?.trim() ?? 'pending (route_task)',\n    }\n  } catch {\n    return undefined\n  }\n}\n\n/** List any loose unorganized files directly in the case root. */\nexport async function listLooseFilesInCase(caseDir: string): Promise<string[]> {\n  const loose: string[] = []\n  try {\n    const entries = await readdir(caseDir, { withFileTypes: true })\n    for (const e of entries) {\n      if (e.isFile() && e.name !== 'CASE.md' && e.name !== 'findings.md') {\n        loose.push(e.name)\n      }\n    }\n  } catch {}\n  return loose\n}\n\n/** Auto-sweep unorganized files from case root into evidence/. */\nexport async function sweepCaseRootFiles(caseDir: string): Promise<string[]> {\n  const swept: string[] = []\n  try {\n    const loose = await listLooseFilesInCase(caseDir)\n    for (const name of loose) {\n      const src = join(caseDir, name)\n      const dest = join(caseDir, 'evidence', name)\n      if (!existsSync(dest)) {\n        await rename(src, dest)\n        swept.push(name)\n      }\n    }\n  } catch {}\n  return swept\n}\n"
